# Generated by build.py from recipe.yml for recipe imap-keep-a-mailbox-off-smtp. Do not edit.
set -e
cd "$(dirname "$0")"
cat > hi.eml <<'EOF'
From: app@example.com
To: viewer@example.com
Subject: Hello

A test message.
EOF
surl --mail-domain example.com --mailbox "viewer@example.com:viewpass;protocols=imap" --mailbox app@example.com:apppass imap://127.0.0.1:8080/ smtp://127.0.0.1:8081/ pop3://127.0.0.1:8082/ &
sleep 1
curl -sS --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt viewer@example.com -T hi.eml smtp://127.0.0.1:8081/example.com
curl -sS -u viewer@example.com:viewpass "imap://127.0.0.1:8080/INBOX;UID=1;SECTION=TEXT"
kill $(jobs -p)
